WITH feature_rows AS (SELECT mktcode,tgtcode,bizdate,value<=low_value AS matched FROM (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx / 10000.0 AS value,MIN(b.lastPx / 10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS low_value FROM `newzl`.`hsj_stock_hq_basic` b) low_stats), ranked_rows AS (SELECT mktcode,tgtcode,bizdate,matched,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate DESC) AS lookback_row FROM feature_rows), qualified AS (SELECT mktcode,tgtcode FROM ranked_rows WHERE lookback_row<=20 GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN matched THEN 1 ELSE 0 END)>=2) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
